/**
 * Hard-deletes the issues with their label links, comments and attachments,
 * recording each project's highest number so it is never reused. Returns the
 * purged comment ids and the megabytes the attachments were counted for.
 */
export async function purgeIssues(
  orgId: OrgId,
  batch: readonly Issue[],
): Promise<{ commentIds: readonly string[]; storageMb: number }> {
  if (batch.length === 0) return { commentIds: [], storageMb: 0 };
  const db = getDb();

  return db.transaction((tx) => {
    const ids = batch.map((issue) => issue.id as string);
    const commentIds: string[] = [];
    let storageMb = 0;

    for (let i = 0; i < ids.length; i += 500) {
      const chunk = ids.slice(i, i + 500);

      for (const row of tx
        .select({ id: comments.id })
        .from(comments)
        .where(and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, chunk)))
        .all()) {
        commentIds.push(row.id);
      }
      for (const row of tx
        .select({ size: attachments.sizeBytes })
        .from(attachments)
        .where(
          and(orgPredicate(attachments.orgId, orgId), inArray(attachments.issueId, chunk)),
        )
        .all()) {
        storageMb += Math.ceil(row.size / (1024 * 1024));
      }

      tx.delete(issueLabels)
        .where(and(orgPredicate(issueLabels.orgId, orgId), inArray(issueLabels.issueId, chunk)))
        .run();
      tx.delete(comments)
        .where(and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, chunk)))
        .run();
      tx.delete(attachments)
        .where(and(orgPredicate(attachments.orgId, orgId), inArray(attachments.issueId, chunk)))
        .run();
    }

    const highest = new Map<string, number>();
    for (const issue of batch) {
      highest.set(
        issue.projectId,
        Math.max(highest.get(issue.projectId) ?? 0, issue.number),
      );
    }
    for (const [projectId, maxNumber] of highest) {
      const existing = tx
        .select({ value: projectNumberMarks.maxNumber })
        .from(projectNumberMarks)
        .where(eq(projectNumberMarks.projectId, projectId))
        .get();
      const next = Math.max(existing?.value ?? 0, maxNumber);
      tx.insert(projectNumberMarks)
        .values({ projectId, orgId, maxNumber: next })
        .onConflictDoUpdate({
          target: projectNumberMarks.projectId,
          set: { maxNumber: next },
        })
        .run();
    }

    for (let i = 0; i < ids.length; i += 500) {
      tx.delete(issues)
        .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, ids.slice(i, i + 500))))
        .run();
    }

    return { commentIds, storageMb };
  });
}''',1)
